const statusEnums = {
  CREATED_BY_VENDOR: 'created_by_vendor',
  CREATED: 'created',
  DRAFT: 'draft',
  APPROVAL_IN_PROGRESS: 'approval_in_progress',
  APPROVED: 'approved',
  REJECTED: 'rejected',
  INACTIVE: 'inactive',
  NOT_INITIATED: 'not_initiated',
  RECONSIDER: 'reconsider',
  RECONSIDER_BY_USER: 'reconsider_by_user',
  CANCELLED: 'cancelled', // applies only to draft po for cancellation
  SHORT_CLOSE: 'short_close', // applies on for short close po
  HOLD: 'hold',
  CONVERTED: 'converted', // PR converted to PO
  PARTIALLY_REJECTED: 'partially_rejected', // HO PR where some state-children are rejected
  REPLACED: 'replaced', // Approval cycle (and its last stage) superseded by an edit-triggered resubmission
};

const statusEnumList = Object.values(statusEnums);

const smallwareStatus = {
  // CREATED: 'CREATED',
  APPROVAL_IN_PROGRESS: 'APPROVAL_IN_PROGRESS',
  APPROVED: 'APPROVED',
  REJECTED: 'REJECTED',
  RECONSIDER: 'RECONSIDER',
};

const smallwareStatusList = Object.values(smallwareStatus);

module.exports = {
  statusEnums,
  statusEnumList,
  smallwareStatus,
  smallwareStatusList,
};

const mongoose = require('mongoose');
const AutoIncrement = require('mongoose-sequence')(mongoose);

const { toJSON, paginate } = require('./plugins');
const { approvalTypes } = require('../config/approvalTypes');
const { statusEnums } = require('../config/statusEnums');

// General Concept:
// An entity (Line Item (Budget Category Item), Purchase Order, GRN, Advance Payment) goes through different levels of approval.
// When an approval is initially created, then the status will be approval_in_progress. An approver for the approval can approve, 
// reject, or reconsider an approval. When an approval is reconsidered by an approver, then it is again sent back to the creator 
// of the approval(After reconsider status becomes reconsider). The creator can edit the approval and resend the approval. After  
// approval is resent, the creator has the same options to approve, reject, and reconsider the approval. When an approval is approved 
// by one approver, then it moves to the next stage of approval. When an approval is approved by all the approvers, then the 
// status of the approval becomes approved. When an approval is rejected by an approver, then the status becomes rejected.
// Note: In case of line item approval, the reconsideration option is not there.

const approvalSchema = mongoose.Schema(
  {
    _id: Number,
    status: {
      type: String,
      enum: statusEnums,
      default: statusEnums.APPROVAL_IN_PROGRESS,
    },
    createdBy: {
      type: Number,
      required: true,
    },
    creatorName: {
      type: String,
      required: true,
    },
    approvalType: {
      type: String,
      enum: approvalTypes,
      required: true,
    },
    site: {
      type: Number,
      ref: 'Location',
      required: true,
    },

    currentStageNumber: {
      type: Number,
      default: 0,
    },
    pendingWith: {
      type: String,
      default: '',
    },
    pendingWithUserId: {
      type: Number,
    },
    pendingWithRoleId: {
      type: Number,
    },
    stages: {
      type: [
        {
          type: Number,
          ref: 'Stage',
        },
      ],
      default: [],
    },
    isVendorGrn: {
      type: Boolean,
      default: false,
    },
    isUserApproved: {
      type: Boolean,
      default: false,
    },
    documentId: {
      type: String,
      default: '',
    },
    document: {
      type: {},
    },
    approved: {
      type: Boolean,
      default: false,
    },
    approvalConfigId: {
      type: Number,
      required: true,
      ref: 'ApprovalConfig',
    },
    updatedBy: {
      type: Number,
      ref: 'User',
    },
    updatedAt: {
      type: Date,
    },
    archive: {
      type: Boolean,
      default: false,
      private: true,
    },
    rejected: {
      type: Boolean,
      default: false,
    },
    reconsiderationRemarks: {
      type: String,
      default: '',
    },
    // Reapproval-lifecycle bookkeeping (PR edit-while-live-cycle feature): cycleNumber orders
    // every Approval cycle ever created for the same document (see documentId), starting at 1.
    // previousApprovalId back-points at the cycle this one superseded, if any -- both are only
    // ever set at creation time in createApproval, never mutated afterward.
    cycleNumber: {
      type: Number,
      default: 1,
    },
    previousApprovalId: {
      type: Number,
      ref: 'Approval',
      default: null,
    },
  },
  {
    timestamps: true,
  }
);

approvalSchema.plugin(toJSON);
approvalSchema.plugin(paginate);
approvalSchema.plugin(AutoIncrement, { id: 'approval_id' });
// Hooks for setting archive as false, and populating necessary data
approvalSchema.pre('findOne', async function (next) {
  this.populate('stages');
  this._conditions.archive = false;
  next();
});

approvalSchema.pre('find', async function (next) {
  this.populate('stages');
  this._conditions.archive = false;
  next();
});

approvalSchema.pre('findById', async function (next) {
  this.populate('stages');
  this._conditions.archive = false;
  next();
});

approvalSchema.pre('countDocuments', async function (next) {
  this._conditions.archive = { $ne: true };
  next();
});

approvalSchema.pre('updateMany', async function (next) {
  this._conditions.archive = { $ne: true };
  next();
});

approvalSchema.pre('findByIdAndUpdate', async function (next) {
  this._conditions.archive = { $ne: true };
  next();
});

const Approval = mongoose.model('Approval', approvalSchema);

module.exports = Approval;

// Field Definitions

// 1. status             - Status of the Approval. (Please read - General Concept for more information)
// 2. name               - Name of the Approval (Name of the Approval Config in General)
// 3. createdBy          - User Id of the creator of the Approval. This is pulse portal user model's _id
// 4. creatorName        - Name of the person who created the Approval
// 5. approvalType       - These can be among the following:
//                         5.1 - po_approval - Purchase Order Approval
//                         5.2 - lineitem_approval - For budget category line item approvas
//                         5.3 - invoice_approval - For Advance Payment and GRN Approval
// 6. site               - All the approvals are created against location in the location master. 
//                         (Refer file location model for more details) 
// 7.currentStageNumber  - This is the stage at which the approval currently is. Generally starts with 1.
//                         When the approval is sent for reconsideration, it then becomes 0.
// 8.pendingWith         - Name of the person with whom approval is pending.
// 9.pendingWithUserId   - Pulse portal user model's user id with whom approval is pending
// 10.pendingWithRoleId  - The Id of the role with whom approval is pending
// 11.stages             - Helps us in tracking this history of approval. 
//                         Who approved approval, comments and other details (Refer stages model)
// 12.documentId         - This is the id of the document for which approval is created.
// 13.document           - This is the document for which approval is created. 
//                         1.In case of po, then entire po is saved.
//                         2.In case of line item, the budget modification document gets saved
//                         3.In case of advance payment/ grn, invoice data gets saved.
//14.approved  -         - This means that approval is approved at all the stages of the process.
//15.approvalConfigId    - This is the id of the approval configuration
//                         (Refer ApprovalConfig model for details)
//16.rejected            - This means that approval is rejected.

const mongoose = require('mongoose');
const AutoIncrement = require('mongoose-sequence')(mongoose);

const { toJSON, paginate } = require('./plugins');
const { statusEnums, statusEnumList } = require('../config/statusEnums');
const { budgetTypeList } = require('../config/budgetTypes');
const { getFinancialYear } = require('../utils/misc2');

// General Concept:
// We create budget for locations (refer location model). We allocate resources to a site.
// There can be 2 types of budget -
// 1. Capex Budget - This is the capital expenditure budget, this is created while starting a site, for allocating resources during its establishment process
// 2. Opex Budget  - This is the operational expenditure budget, this created for allocation of resources during the operation of the site

const budgetSchema = mongoose.Schema(
  {
    _id: Number,
    name: {
      type: String,
    },
    budgetType: {
      type: String,
      enum: budgetTypeList,
    },
    status: {
      type: String,
      enums: statusEnumList,
      default: statusEnums.CREATED,
    },
    site: {
      type: Number,
      required: true,
      ref: 'Location',
    },
    siteCode: {
      type: String,
    },
    siteName: {
      type: String,
      // required: true,
    },
    storeId: {
      type: Number,
    },
    // category: {
    //   type: Number,
    //   ref: 'Category',
    //   required: true,
    // },
    lineItems: {
      type: [
        {
          type: Number,
          ref: 'LineItem',
        },
      ],
      default: [],
    },
    createdBy: {
      type: Number, // user id
      required: true,
    },
    creatorName: {
      type: String,
      required: true,
    },
    initialApproval: {
      type: Boolean,
      default: false,
    },
    modifiedBudgetCost: {
      type: Number,
      default: 0,
    },
    reservedAmount: {
      type: Number,
      default: 0,
    },
    utilizedAmount: {
      type: Number,
      default: 0,
    },
    availableBudgetCost: {
      type: Number,
      default: 0,
    },
    financialYear: {
      type: String,
      default: getFinancialYear, // Auto-generate on document creation
    },
    updatedBy: {
      type: Number,
      ref: 'User',
    },
    updatedAt: {
      type: Date,
    },
    archive: {
      type: Boolean,
      default: false,
      private: true,
    },
    apiVersion: {
      type: String,
      default: 'v2',
      immutable: true,
    },
  },
  {
    timestamps: true,
  }
);

budgetSchema.plugin(toJSON);
budgetSchema.plugin(paginate);
budgetSchema.plugin(AutoIncrement, { id: 'budget_id' });
// Hooks for setting archive as false, and populating necessary data
budgetSchema.pre('findOne', async function (next) {
  this.populate('lineItems');
  // this.populate('category');
  this._conditions.archive = false;
  this._conditions.apiVersion = 'v2';
  next();
});

budgetSchema.pre('find', async function (next) {
  this.populate('lineItems');
  // this.populate('category');
  this._conditions.archive = false;
  this._conditions.apiVersion = 'v2';
  next();
});

budgetSchema.pre('findById', async function (next) {
  this.populate('lineItems');
  // this.populate('category');
  this._conditions.archive = false;
  this._conditions.apiVersion = 'v2';
  next();
});

budgetSchema.pre('findOneAndUpdate', async function (next) {
  this._conditions.archive = false;
  this._conditions.apiVersion = 'v2';
  next();
});

const Budget = mongoose.model('Budget', budgetSchema);

module.exports = Budget;

// Field Definitions:

// 1. name                 - Name of the budget, this is name of the site for which we are creating the budget
// 2. budgetType           - This is the type of budget (refer General Concept)
// 3. status               - Status of the budget is generally approved when the budget is created, but we can put it on hold
//                           In that case that the status of the budget will be inactive.
// 4. site                 - This is  the name of the site for the budget is created
// 5. siteCode             - This is the code of the site for the budget
// 6. siteName             - This is the name of the site for the budget
// 7. storeId (deprecated) - This is the id of the store for the budget
// 8. lineItems            - (Refer line item model) These are the resources which we have to allocate to a budget
// 9. createdBy            - This is the user _id of the user who created the budget
// 10 creatorName          - The name of the person who created the budget
// 11.initialApproval      - This means that budget is initially approved or not

const mongoose = require('mongoose');
const AutoIncrement = require('mongoose-sequence')(mongoose);

const { toJSON, paginate } = require('./plugins');
const { statusEnums } = require('../config/statusEnums');
const { paymentStatusEnums } = require('../config/paymentStatusEnums');
const { v4 } = require('uuid');
const { getFinancialYear } = require('../utils/misc2');

// General Concept:
// After a purchase order has been approved, we need to keep track of the goods that we have received for the purchase order
// Initially when a grn is created in the draft stage then we do not track how many quantity we have received.

// When send/resend grn for approval then we inward the quantity for those items (Item Model) of that grn in the purchase order
// i.e. we increase itemSchema.inwardedQuantity of the item in Purchase Order.
// Note - Please refer updateInwardedQuantity function (path src\services\purchase-order-service\service2.js) to understand how this works.

// When all the items of the purchase order are received, then the key allowInward - in the purchase order becomes false.
// This means that we cannot receive any more quantity for the purchase order, hence we cannot create grn for it.

// When we reject/reconsider grn, then we decrease itemSchema.inwardedQuantity in purchase order by the grn items.
// Note - Please refer revertGrnItemsBackInPo function (src src\services\purchase-order-service\service2.js)

// receivedExtraCharges mirrors receivedItems, but for the purchase order's FIXED_AMOUNT extraCharges rows instead of items.
// Unlike items, extra-charge quantity is NOT booked when the grn is sent/resent for approval - it is only booked
// (extraChargeItemSchema.inwardedQuantity incremented) when the grn reaches final approval.
// Note - Please refer updateInwardedExtraChargeQuantity/revertGrnExtraChargesBackInPo functions (path src\services\purchase-order-service\service2.js)

// Please note that all the grns have to be unqiue by the following paramters:

//1. financialyear
//2. invoiceNumber
//3. vendorCode

const grnReceivedItemSchema = mongoose.Schema({
  _id: {
    type: String,
    default: v4,
  },
  poItemId: {
    type: String,
    required: true,
  },
  receivedQuantity: {
    type: Number,
    required: true,
  },
  comments: {
    type: String,
  },
  hsnCode: {
    type: String,
  },
});

const grnReceivedExtraChargeSchema = mongoose.Schema({
  _id: {
    type: String,
    default: v4,
  },
  poExtraChargeId: {
    type: String,
    required: true,
  },
  receivedQuantity: {
    type: Number,
    required: true,
  },
  comments: {
    type: String,
  },
});

const grnSchema = mongoose.Schema(
  {
    _id: Number,
    status: {
      type: String,
      enum: statusEnums,
    },
    purchaseOrderId: {
      type: Number,
      ref: 'PurchaseOrder',
      required: true,
    },
    poNumber: {
      type: String,
      required: true,
    },
    site: {
      type: Number,
      ref: 'Location',
      required: true,
    },
    vendorCode: {
      type: String,
      // required: true,
    },
    receivedItems: [grnReceivedItemSchema],
    receivedExtraCharges: {
      type: [grnReceivedExtraChargeSchema],
      default: [],
    },
    inwardDate: {
      type: Date,
      required: true,
    },
    remarks: {
      type: String,
    },
    invoiceDate: {
      type: Date,
      required: true,
    },
    invoiceNumber: {
      type: String,
      required: true,
    },
    financialyear: {
      type: Number,
      required: true,
    },
    invoiceAmount: {
      type: Number,
      required: true,
      // min: 0,
    },
    invoiceUrls: {
      type: [String],
      default: [],
    },
    additionalDocUrls: {
      type: [String],
      default: [],
    },
    paymentStatus: {
      type: String,
      enum: paymentStatusEnums,
      default: paymentStatusEnums.INVOICE_NOT_UPLOADED,
    },
    invoiceDataId: {
      type: Number,
    },
    grnNo: {
      type: String,
      required: true,
    },
    approvalId: {
      type: Number,
      ref: 'Approval',
    },
    creatorName: {
      type: String,
      required: true,
    },
    createdBy: {
      type: Number,
      required: true,
    },
    isVendorGrn: {
      type: Boolean,
      default: false,
    },
    poCreatorId: {
      type: Number,
    },
    prCreatorId: {
      type: Number,
      default: null,
    },
    department: {
      type: Number,
    },
    msmeDeclaration: {
      type: String,
    },
    holdComment: {
      type: String,
    },
    financialYear: {
      type: String,
      default: getFinancialYear, // Auto-generate on document creation
    },
    updatedBy: {
      type: Number,
      ref: 'User',
    },
    updatedAt: {
      type: Date,
    },
    archive: {
      type: Boolean,
      default: false,
      private: true,
    },
  },
  {
    timestamps: true,
  }
);

grnSchema.plugin(toJSON);
grnSchema.plugin(paginate);
grnSchema.plugin(AutoIncrement, { id: 'grn_id' });

grnSchema.pre('find', async function (next) {
  this.populate('purchaseOrderId');
  this.populate('approvalId');
  this._conditions.archive = { $ne: true };
  next();
});
grnSchema.pre('findOne', async function (next) {
  this.populate('purchaseOrderId');
  this.populate('approvalId');
  this._conditions.archive = { $ne: true };
  next();
});
grnSchema.pre('findById', async function (next) {
  this.populate('purchaseOrderId');
  this.populate('approvalId');
  this._conditions.archive = { $ne: true };
  next();
});

grnSchema.pre('countDocuments', async function (next) {
  this._conditions.archive = { $ne: true };
  next();
});

const Grn = mongoose.model('Grn', grnSchema);

module.exports = Grn;

// Field Definitions:

// 1. status             -  Status of the goods received notes. Just like a purchase order, grn can be sent for approval or saved as draft.
//                          Then approval process is similar to other approvals
// 2. purchaseOrderId    -  Id of the purchase order for which grn has been created.
// 3. department         -  Department of the grn's creator; falls back to the purchase order's department (the PO creator's) when the grn creator has none mapped (vendor/store)
// 4. poNumber           -  This is purchase order's po number for which grn has been created. It is same as purchase order's po number(Refer PO Model).
// 5. site               -  This is the location of the purchase order
// 6. vendorCode         -  This is the vendor code for the purchase order
// 7. receivedItems      -  These are the purchase order's items that in grn we have marked that we have received these
//                          Let us try to understand fields here :
//                          1. poItemId         - This is the purchase order's item (_id field in itemSchema in PurchaseOrder Model)
//                          2. receivedQuantity - This is the purchase order's quantity of item that we have received
//                          3. comments         - These are the comments that user fills with every item in the UI
//                          4. hsnCode          - This is generally the purchase order's item's hsn code. But user can change it from UI, while creating/updating GRN
// 7a. receivedExtraCharges - Mirrors receivedItems, but for the purchase order's FIXED_AMOUNT extraCharges rows (percentage charges are not received via grn)
//                          1. poExtraChargeId  - This is the purchase order's extra charge row (_id field in extraChargeItemSchema in PurchaseOrder Model)
//                          2. receivedQuantity - This is the quantity of that extra charge received in this grn
//                          3. comments         - These are the comments that user fills with every extra charge row in the UI
//                          Unlike receivedItems, this quantity is only booked into the purchase order's extraCharges.inwardedQuantity when the grn reaches final approval, not when it is sent/resent for approval
// 8.  inwardDate        - This is the date when we received the goods for the purchase order. In UI this is known as  -  Material/Service Received Date
// 9.  remarks           - These are the remarks that user enters while creating/updating the grn
// 10. invoiceDate       - This is the invoice date
// 11. invoiceNumber     - This is the invoice number
// 12. financialyear     - This is the financial year when the purchase order was created
// 13. invoiceAmount     - This is the amount of the invoice
// 14. invoiceUrls       - These are the invoice attachments
// 15. additionalDocUrls - These are the additional attachments
// 16. paymentStatus     - This is the payment status of the GRN. These can be understood through different stages as follows:
//                           1. Initially when the grn is saved as draft the payment status is Invoice Not uploaded.
//                           2. When the GRN is sent for approval, the payment status is Approval In Progress
//                           3. When the GRN is reconsidered, the payment status is reconsidered
//                           4. When the GRN is rejected, the payment status is rejected
//                           5. When the GRN is fully approved, the payment status becomes pending
//                           6. After the grn is fully approved and payment is made, then the payment status will be partial payment
//                           7. When the total amount paid  is equal to the invoiceAmount then the payment status will be completed
// 17. invoiceDataId     - This is the id of the invoice data(Refer In Invoice Data Model)
// 18. grnNo             - When a grn is created, we assign a unique code. This is generated using getMasterCode function (refer getMasterCode function path - src\services\counter.service.js)
// 19. approvalId        - This is the id of the approval created for the grn
// 20. creatorName       - This is the name of the creator of the grn
// 21. createdBy         - This is user _id of the person who created the grn
// 22. prCreatorId       - This is user _id of the creator of the Purchase Request linked to this grn's
//                         purchase order (via PurchaseOrder.purchaseRequestId), or null if not linked/resolved

const mongoose = require('mongoose');
const AutoIncrement = require('mongoose-sequence')(mongoose);

const { toJSON, paginate } = require('./plugins');
const { invoiceTypeList } = require('../config/enums');
const { paymentStatusEnums } = require('../config/paymentStatusEnums');
const { statusEnumList } = require('../config/statusEnums');
const { getFinancialYear } = require('../utils/misc2');

// General Concept:
// Here we store all the invoice details related to the Advance/GRN invoice
// For Advance Payment, Invoice Data is created when we initiate advance payment for the purchase order
// For GRN, invoice data is created when grn is sent for approval

const invoicedataSchema = mongoose.Schema(
  {
    _id: Number,
    status: {
      type: String,
      enum: statusEnumList,
    },
    invoiceDocumentNumber: {
      type: String,
      required: true,
    },
    // Invoice Details
    invoiceType: {
      type: String,
      enum: invoiceTypeList,
      required: true,
    },
    poId: {
      type: Number,
      ref: 'PurchaseOrder',
      required: true,
    },
    department: {
      // Cascades from the linked PurchaseOrder/GRN's department -- null for POs raised
      // by STORE role users, so this can't be required: true here either.
      type: Number,
    },
    poNumber: {
      type: String,
      required: true,
    },
    grnNo: {
      type: String,
    },
    grnId: {
      type: Number,
      ref: 'Grn',
    },
    invoiceDate: {
      type: Date,
      required: true,
    },
    invoiceNumber: {
      type: String,
      required: true,
    },
    invoiceAmount: {
      type: Number,
      required: true,
    },
    sentAmount: {
      type: Number,
      default: 0,
    },
    invoiceUrls: {
      type: [String],
      default: [],
    },
    additionalDocUrls: {
      type: [String],
      default: [],
    },

    // Vendor Details
    vendorCode: {
      type: String,
      // required: true,
    },
    vendorGST: {
      type: String,
      // required: true,
    },
    vendorPAN: {
      type: String,
      // required: true,
    },
    vendorAddress: {
      type: String,
      // required: true,
    },
    city: {
      type: String,
      // required: true,
    },
    state: {
      type: String,
      // required: true,
    },

    // Payment Details
    paymentDetails: {
      type: [
        {
          dateOfPayment: {
            type: Date,
            required: true,
          },
          utr: {
            type: String,
            required: true,
          },
          tdsAmount: {
            type: Number,
            default: 0,
          },
          paymentAmount: {
            type: Number,
            required: true,
          },
          paymentDocUrls: {
            type: [String],
            default: [],
          },
        },
      ],
      default: [],
    },

    paymentStatus: {
      type: String,
      enum: paymentStatusEnums,
      default: paymentStatusEnums.INVOICE_NOT_UPLOADED,
    },
    approvalId: {
      type: Number,
      ref: 'Approval',
    },
    archive: {
      type: Boolean,
      default: false,
      private: true,
    },
    creatorName: {
      type: String,
      required: true,
    },
    site: {
      type: Number,
      ref: 'Location',
      required: true,
    },
    financialYear: {
      type: String,
      default: getFinancialYear, // Auto-generate on document creation
    },
    createdBy: {
      type: Number,
      required: true,
    },
    poCreatorId: {
      type: Number,
    },
    prCreatorId: {
      type: Number,
      default: null,
    },
    updatedBy: {
      type: Number,
      ref: 'User',
    },
