// Field Definitions:

// 1.  approvalId                - The ID of the approval of the purchase order.
// 2.  company                   - This is the company for which purchase order is created
// 3.  allowInward               - For tracking that whether we have received all the purchase order items or not
// 4.  isShortClosed             - For tracking that whether purchase order is short closed or not
// 5.  department                - This is the department for which purchase order is created
// 6.  site                      - This is the location for which purchase order is created
// 7.  siteName(depracated)      - This is the name of the site
// 8.  siteCode(depracated)      - This the code of the site
// 9.  storeId(depracated)       - This is the storeId associated with the site
// 10. poType                    - This is the type of purchase order. It can be capex/po
// 11. budget                    - This is the _id of the budget for which purchase order is created
// 12. status                    - This is the status of the purchase order. It can be among the following:
//                                 1. draft                - When we create draft of the purchase order
//                                 2. approval_in_progress - When the purchase order is sent for approval
//                                 3. approved             - When the purchase order is fully approved. After po is fully approved, advance payment can be initiated(when advance percentage(advance.advancePercentage) is greater than 0)
//                                                           and grn can also be created.
//                                 4. rejected             - When the purchase order is rejected during approval process
//                                 5. reconsider           - When the purchase order is reconsidered by one of the approver
//                                 6. cancelled            - When the purchase order is cancelled
//                                 7. short_close          - When the purchase order is short closed
// 13. vendorCode               - This is code of the vendor (invoice submission vendor). You can refer Vendor Master(Masters Tab, Vendor Sub Tab) for viewing complete vendor details
// 14. vendorName               - This is the name of the vendor
// 15. vendorGst                - This is the gst of the vendor
// 16. vendorPancard            - Pan card details of the vendor
// 17. items                    - These are the items(Refer Item Model) for which we have created purchase order. Let us try to understand the fields here:
//                                1.  lineItem             - _id of the line item(Refer Line Item Model) which is associated with the item.
//                                2.  item                 - _id of the item (Refer Item Model)
//                                3.  uom                  - UOM of the item
//                                4.  quantity             - Quantity of the item
//                                5.  rate                 - Price of the item
//                                6.  amount               - Amount of the item. amount = quantity * rate
//                                7.  taxRate              - Tax rate of the item
//                                8.  taxAmount            - Tax amount of the item. taxAmount = (quantity * rate * taxRate) / 100
//                                9.  totalAmount          - Total amount of the item. totalAmount = amount + taxAmount
//                                10. description          - Description of the item
//                                11. remarks              - Remarks of the item
//                                12. inwardedQuantity     - After PO is fully approved and we create GRNs (Refer GRN Model) for it, we track the quantity of the item received.
//                                13. allowInward          - To track whether we received all the quantity of the item or not.
//                                                           allowedInward is false, when inwardedQuantity === quantity, otherwise it is true
//                                14. hsnCode              - HSN Code of the item
//                                15. isShortClosed        - Whether the item is short closed or not
// 18. poNumber                 - Unique code generated for every purchase order when it gets created.Refer function  -  getPoNumber (path - src\utils\number-series.js) for more details
// 19. poDate                   - This is purchase order date. It is generally equivalent to the purchase order date
// 20  agreement                - Whether there is an agreement with the vendor or not. It can be Yes/No
// 21. paymentTerms             - Vendor payment terms
// 22. termsAndConditions       - Terms and conditions of the purchase order
// 23. currency                 - Currency of the purchase order
// 24. deliveryLocationId       - _id of the delivery location
// 25. billingLocationId        - _id of the billing location
// 26. remarks                  - Agreement remarks for the purchase order
// 27. advance                  - Advance details for the purchase order
//                                1.  advancePercentage    - Percentage of the advance payment. When the advancePercentage is greater than 0, then only we can Initiate Advance Payment for the purchase orders
//                                2.  advanceAmount        - Amount of the advance payment(This is the sum of the amounts for all the items)
//                                3.  adavancedApproved    - Whether advance payment has been approved or not
//                                4.  advanceStatus        - Status of the advance payment
//                                                           1. When the purchase order is created, then the advanceStatus is not_initiated
//                                                           2. When the advance payment is initiated, then the advanceStatus is approval_in_progress
//                                                           3. When the advance payment is rejected, then the advanceStatus is rejected
//                                                           4. When the advance payment is reconsidered, then the advanceStatus is reconsidered
//                                                           5. When the advance payment is approved, then the advanceStatus is approved
//                                5. grnReceived     - To check that the whether grn is created for a po or not
// 28. forex                    - The rate of the foreign exchange
// 29. createdBy                - The _id of the person who created the purchase order
// 30  creatorName              - The name of the creator who created the purchase order
// 31. amount                   - Sum of the amount of all the items in the purchase order
// 32. taxAmount                - Sum of the tax amount of all the items in the purchase order
// 33. totalAmount              - Sum of 31. and 32.
// 34  documentLinks            - All the documents attached to the purchase order
// 35. extraCharges              - Header-level charges applied to this purchase order (e.g. Freight, Insurance, Packing), snapshotted from the ExtraCharge master at the time they were applied. Let us try to understand the fields here:
//                                1.  extraChargeId         - _id of the extra charge master (Refer ExtraCharge Model) that was used
//                                2.  chargeCode            - Code of the extra charge, as on the ExtraCharge master at the time of applying
//                                3.  chargeName            - Name of the extra charge, as on the ExtraCharge master at the time of applying
//                                4.  hsnCode               - HSN code of the extra charge, as on the ExtraCharge master at the time of applying
//                                5.  calculationType       - How the charge value is calculated (Fixed Amount/Percentage)
//                                6.  valueMode             - Whether the value came from a configured default or was entered manually (Configured Value/Manual Entry)
//                                7.  value                 - The charge value applied on this purchase order. For FIXED_AMOUNT charges this is the unit rate: chargeAmount = quantity * value. For PERCENTAGE charges it is the % applied to the PO subtotal (quantity is not used)
//                                8.  quantity               - Required for FIXED_AMOUNT charges (e.g. number of units/trips); not applicable to PERCENTAGE charges
//                                9.  uom                    - Required for FIXED_AMOUNT charges; unit of measure for the quantity above
//                                10. taxable               - Whether this charge is subject to tax on this purchase order
//                                11. taxRate               - Tax rate applied to the charge
//                                12. chargeAmount          - Charge amount before tax
//                                13. taxAmount             - Tax amount on the charge
//                                14. totalChargeAmount     - chargeAmount + taxAmount
//                                15. affectsPOTotal        - Whether this charge is included in the PO total
//                                16. affectsBudget         - Whether this charge is considered against budget. Defaults true; when true (the default), the charge's chargeAmount+taxAmount is allocated across the PO's line items (see allocateExtraChargesToLineItems, src\utils\misc.js) and included in the LineItem.availableAmount deduction/restoration alongside the item totals
//                                17. remarks               - Optional free-text note for this charge row
//                                18. inwardedQuantity      - For FIXED_AMOUNT charges only. After the PO is approved and GRNs are approved against this charge, tracks the quantity received so far. Unlike item quantities (booked when a GRN is sent for approval), this is only incremented when a GRN reaches final approval (Refer updateInwardedExtraChargeQuantity, path src\services\purchase-order-service\service2.js)
//                                19. allowInward           - Whether this charge can still be received against. Set true for FIXED_AMOUNT charges with a quantity when the PO is fully approved; becomes false once inwardedQuantity reaches quantity
// 36. extraChargesTotal (virtual, not stored) - Sum of chargeAmount + taxAmount across extraCharges rows where affectsPOTotal is true
// 37. grandTotal (virtual, not stored)        - totalAmount + extraChargesTotal. amount/taxAmount/totalAmount themselves stay items-only (see 31-33); budget deduction and approval-threshold checks are computed separately (not from this virtual) but DO include extraCharges -- see checkLineItemsAmount/allocateExtraChargesToLineItems, src\services\line-item-service\po-line-item-check.js and src\utils\misc.js

const mongoose = require('mongoose');
const AutoIncrement = require('mongoose-sequence')(mongoose);
const { v4 } = require('uuid');

const { toJSON, paginate } = require('./plugins');
const { statusEnums, statusEnumList } = require('../config/statusEnums');
const { unitList } = require('../config/enums');
const { getFinancialYear } = require('../utils/misc2');

// General Concept:
// A Purchase Requisition (PR) is a formal request to purchase goods or services, raised before
// a Purchase Order is created. It sits between Budget/LineItem allocation and PO commitment.
//
// Scopes:
//   SINGLE_STORE - raised by or for one specific store
//   HEAD_OFFICE  - raised from HO; can target multiple stores, cities, or regions
//
// For HEAD_OFFICE PRs that span multiple states, the system auto-creates one child PR per
// unique Location.state (GST compliance). The parent PR is a coordination record only;
// only child PRs go through approval and convert to POs.
//
// Item population methods:
//   MANUAL                 - row-by-row item selection
//   EXCEL_UPLOAD           - upload Excel template (HO users only)
//   CATEGORY_AUTO_POPULATE - auto-fill all items for a category/sub-category
//   BULK_UPLOAD            - multi-store Excel creating multiple PRs (HO users only)

// Per-store allocation of a PR item's requested quantity. Each item's `quantity` is
// derived as the sum of allocations[].requestedQuantity (see prItemSchema.pre('validate')
// below) once allocations exist -- allocations are the source of truth for store-wise
// balances; quantity/convertedQuantity/remainingQuantity below stay as pooled mirrors kept
// in sync for existing readers (dashboard-service, pr-pdf) that only ever read the pool.
const prItemAllocationSchema = mongoose.Schema(
  {
    _id: false,
    allocationId: {
      type: String,
      default: v4,
    },
    storeId: {
      type: Number,
      ref: 'Location',
      required: true,
    },
    requestedQuantity: {
      type: Number,
      required: true,
      min: 0,
    },
    reservedQuantity: {
      type: Number,
      default: 0,
      min: 0,
    },
    convertedQuantity: {
      type: Number,
      default: 0,
      min: 0,
    },
    shortClosedQuantity: {
      type: Number,
      default: 0,
      min: 0,
    },
  },
  { _id: false }
);

// availableQuantity is intentionally never stored -- always derived so it can never go
// stale relative to the four counters that actually get written by allocation.service.js.
prItemAllocationSchema.virtual('availableQuantity').get(function () {
  return this.requestedQuantity - this.reservedQuantity - this.convertedQuantity - this.shortClosedQuantity;
});
prItemAllocationSchema.set('toJSON', { virtuals: true });

const prItemSchema = mongoose.Schema({
  _id: {
    type: String,
    default: v4,
  },
  lineItem: {
    type: Number,
    ref: 'LineItem',
  },
  item: {
    type: Number,
    ref: 'Item',
  },
  // Snapshot of the item's resolved category mapping at PR-item-creation time (manual
  // add, auto-populate, or excel/bulk upload -- see resolveCategoryMapping in
  // item-service/resolve-category-mapping.js). PO items converted from this PR line
  // inherit category/subCategory/categoryMappingId from here rather than re-resolving.
  category: {
    type: Number,
    ref: 'Category',
  },
  subCategory: {
    type: Number,
    ref: 'SubCategory',
  },
  categoryMappingId: {
    type: String,
  },
  itemName: {
    type: String,
  },
  itemCode: {
    type: String,
  },
  description: {
    type: String,
  },
  hsnCode: {
    type: String,
  },
  uom: {
    type: String,
    enum: unitList,
  },
  quantity: {
    type: Number,
    required: true,
    min: 0,
  },
  estimatedRate: {
    type: Number,
    min: 0,
  },
  estimatedAmount: {
    type: Number,
  },
  taxRate: {
    type: Number,
    min: 0,
    default: 0,
  },
  estimatedTaxAmount: {
    type: Number,
  },
  estimatedTotalAmount: {
    type: Number,
  },
  remarks: {
    type: String,
  },
  // Which source estimatedRate/taxRate were resolved from at last write time -- see
  // resolveEffectiveUnitPrice in item-service/resolve-item-price.js. Purely informational
  // (audit/debugging); nothing reads it back to make decisions.
  priceSource: {
    type: String,
    enum: ['CLIENT_SUPPLIED', 'ITEM_MASTER', 'VENDOR_MAPPING'],
  },
  rateContract: {
    type: Boolean,
    default: false,
  },
  vendorCode: {
    type: String,
  },
  vendorName: {
    type: String,
  },
  requiredByDate: {
    type: Date,
  },
  budgetHead: {
    type: String,
  },
  convertedQuantity: {
    type: Number,
    default: 0,
  },
  remainingQuantity: {
    type: Number,
    default: null,
  },
  // Pooled mirror of this item's total short-closed quantity across all its allocations --
  // kept in sync by recomputeConversionStatus alongside convertedQuantity/remainingQuantity
  // above, the same way. Together the three should always sum to this item's PR Qty
  // (convertedQuantity + shortClosedQuantity + remainingQuantity == quantity), modulo any
  // quantity transiently sitting in reservedQuantity between reserve and convert.
  shortClosedQuantity: {
    type: Number,
    default: 0,
  },
  // Per-store consumption for HEAD_OFFICE/multi-store PRs (storeSelectionType in
  // SPECIFIC_STORES/CITY/STATE/REGION), where this item's pooled `quantity` is split
  // evenly across pr.selectedSites. convertedQuantity/remainingQuantity above remain the
  // pooled totals across all stores; this array is additional per-store bookkeeping so a
  // PO against one store doesn't affect another store's displayed balance. Unused/empty
  // for SINGLE_STORE PRs.
  storeConsumption: {
    type: [
      {
        _id: false,
        site: { type: Number, ref: 'Location' },
        convertedQuantity: { type: Number, default: 0 },
      },
    ],
    default: [],
  },
  // Store-wise allocations of this item's requested quantity -- the source of truth for
  // per-store balances going forward (see allocation.service.js). Populated either by the
  // client (new HEAD_OFFICE PRs must supply one entry per selected store) or derived
  // server-side for SINGLE_STORE/legacy PRs (see convert-to-po.service.js ensureAllocations).
  allocations: {
    type: [prItemAllocationSchema],
    default: [],
  },
});

// quantity is derived from allocations once they exist, so it can never drift from the
// sum of what was actually allocated per store. Items with no allocations yet (not
// migrated/derived) keep `quantity` independently settable exactly as before.
prItemSchema.pre('validate', function (next) {
  if (this.allocations && this.allocations.length > 0) {
    this.quantity = this.allocations.reduce((sum, allocation) => sum + (allocation.requestedQuantity || 0), 0);
  }
  next();
});

const purchaseRequestSchema = mongoose.Schema(
  {
    _id: Number,

    prNumber: {
      type: String,
    },
    prDate: {
      type: Date,
    },

    // ── Scope ──────────────────────────────────────────────────────────────────
    prScope: {
      type: String,
      enum: ['SINGLE_STORE', 'HEAD_OFFICE'],
      required: true,
    },
    prType: {
      type: String,
      enum: ['CAPEX', 'OPEX'],
      required: true,
