      default: [],
    },
    selectedStates: {
      type: [String],
      default: [],
    },
    selectedRegions: {
      type: [String],
      default: [],
    },
    selectedSites: {
      type: [{ type: Number, ref: 'Location' }],
      default: [],
    },

    // ── GST compliance ─────────────────────────────────────────────────────────
    // Each PR document covers exactly one GST state. HO PRs spanning multiple
    // states are split into child PRs, one per state.
    gstState: {
      type: String,
      default: null,
    },
    gstNumber: {
      type: String,
      default: null,
    },

    // ── Parent-child hierarchy (HO multi-state splitting) ──────────────────────
    isParentPR: {
