    },

    // ── Organisation ───────────────────────────────────────────────────────────
    company: {
      type: Number,
      ref: 'Company',
    },
    department: {
      // null for STORE role transactions (see isStoreRole(req.user) in
      // purchase-request.controller.js) -- required for every other role, enforced
