      type: Number,
    },
    budget: {
      type: Number,
      ref: 'Budget',
    },

    // ── Item population ────────────────────────────────────────────────────────
    itemPopulationMethod: {
      type: String,
      enum: ['MANUAL', 'EXCEL_UPLOAD', 'CATEGORY_AUTO_POPULATE', 'BULK_UPLOAD'],
      default: 'MANUAL',
    },
    items: {
      type: [prItemSchema],
      default: [],
    },

    // ── Preferred vendor (optional, shown when PRConfig.vendorFieldEnabled) ────
    preferredVendorCode: {
      type: String,
      default: null,
    },
    preferredVendorName: {
      type: String,
      default: null,
    },
    vendorRemarks: {
      type: String,
      default: null,
    },
    paymentTerms: {
      type: String,
      default: null,
    },

    // ── Totals ─────────────────────────────────────────────────────────────────
    totalEstimatedAmount: {
      type: Number,
      default: 0,
    },
    totalEstimatedTaxAmount: {
      type: Number,
      default: 0,
    },
    totalEstimatedGrossAmount: {
      type: Number,
      default: 0,
    },

    justification: {
      type: String,
    },
    documentLinks: {
      type: [String],
      default: [],
    },

    // ── Approval ───────────────────────────────────────────────────────────────
    approvalId: {
      type: Number,
      ref: 'Approval',
      default: null,
