    // Append-only history of every approval cycle this PR has ever had, in the order they were
    // superseded -- pushed (never removed/overwritten) whenever an edit or a reconsider-resubmit
    // starts a new cycle, right before approvalId is repointed to the new one. Mirrors the
    // purchaseOrderIds pattern just below: an explicit, permanent link from the PR to its own
    // history, rather than an orphaned Approval doc only findable by reverse-querying documentId.
    previousApprovalIds: {
      type: [{ type: Number, ref: 'Approval' }],
      default: [],
    },

    // ── Conversion ─────────────────────────────────────────────────────────────
    purchaseOrderIds: {
      type: [{ type: Number, ref: 'PurchaseOrder' }],
      default: [],
    },

    // True for pre-allocation-tracking HEAD_OFFICE PRs whose real per-store split can't
